use futures::StreamExt;
use rig::agent::MultiTurnStreamItem;
use rig::prelude::*;
use rig::providers::openai::{self, OpenAI};
use rig::streaming::{Item, StreamEvent};
use std::io::Write;


#[tokio::main]
async fn main() -> anyhow::Result<()> {
    let agent = AgentBuilder::new(OpenAI::from_env()?.completion(openai::GPT_5_5))
        .preamble("You are a storyteller.")
        .build();


    let mut stream = agent.prompt("Tell me a short story about a robot.").stream();


    while let Some(item) = stream.next().await {
        match item? {
            MultiTurnStreamItem::StreamAssistantItem(Item::Event(StreamEvent::Text { text, .. })) => {
                print!("{text}");
                std::io::stdout().flush()?;
            }
            MultiTurnStreamItem::FinalResponse(response) => {
                println!("\n\n{} tokens used", response.usage().total_tokens.unwrap_or(0));
            }
            _ => {}
        }
    }


    Ok(())
}

use rig::streaming::{Item, PartKind, StreamEvent, parse_partial_arguments};
use std::collections::HashMap;


let mut stream = agent.prompt("Write a haiku to notes.md").max_turns(3).stream();
let mut args_so_far: HashMap<usize, String> = HashMap::new();


while let Some(item) = stream.next().await {
    match item? {
        MultiTurnStreamItem::StreamAssistantItem(Item::Event(event)) => match event {
            StreamEvent::Start { part, kind: PartKind::ToolCall, name } => {
                println!("calling {name:?}");
                args_so_far.insert(part.index(), String::new());
            }
            StreamEvent::Arguments { part, json } => {
                if let Some(args) = args_so_far.get_mut(&part.index()) {
                    args.push_str(&json);
                    println!("  args so far: {:?}", parse_partial_arguments(args));
                }
            }
            _ => {}
        },
        MultiTurnStreamItem::ToolResult { tool_result } => {
            println!("result for {}", tool_result.call);
        }
        _ => {}
    }
}

let mut stream = agent.prompt("Hello!").stream();
while let Some(item) = stream.next().await {
    match item? {
        MultiTurnStreamItem::CompletionCall(call) => {
            println!("call {}: {:?} input tokens", call.call_index, call.usage.input_tokens);
        }
        MultiTurnStreamItem::FinalResponse(response) => {
            println!("total: {:?} tokens", response.usage().total_tokens);
        }
        _ => {}
    }
}

use rig::agent::stream_to_stdout;


let mut stream = agent.prompt("Hello!").stream();
let response = stream_to_stdout(&mut stream).await?;
println!("\n{} model calls", response.requests());

let (run, mut events) = agent.prompt("Tell me a joke").run_channel();
let handle = tokio::spawn(run);


// Later, from a synchronous tick:
while let Some(item) = events.try_next() {
    if let MultiTurnStreamItem::FinalResponse(response) = item {
        println!("{}", response.output());
    }
}


let response = handle.await??;

use rig::completion::CompletionRequest;
use rig::streaming::{Item, StreamEvent};


let model = OpenAI::from_env()?.completion(openai::GPT_5_5);
let request = CompletionRequest::new(Message::user("Name three rivers."))
    .preamble("Answer briefly.")
    .max_tokens(200);


let mut stream = model.stream(request)?;
while let Some(item) = stream.next().await {
    if let Item::Event(StreamEvent::Text { text, .. }) = item? {
        print!("{text}");
    }
}


let response = stream.finish().await?;
println!("\nfinish reason: {:?}, usage: {:?}", response.finish_reason(), response.usage);
